// Local licensed catalog; existing inline data remains the offline/fetch-error fallback.
const CATALOG_URL='assets/data/avtovip-extended-catalog.json';
function mergeExtendedCatalog(data){
  if(!data||typeof data!=='object')return;
  for(const category of DATA){
    if(category.id==='car')continue; // Original automobile flow is managed separately.
    const entries=data[category.id];if(!entries||typeof entries!=='object'||Array.isArray(entries))continue;
    const names=new Set(category.brands);
    MODEL_CATALOG[category.id] ||= {};
    for(const [brand,list] of Object.entries(entries)){
      if(!brand||!Array.isArray(list))continue;
      names.add(brand);
      const old=MODEL_CATALOG[category.id][brand]||[];
      MODEL_CATALOG[category.id][brand]=[...new Set([...old,...list.filter(x=>typeof x==='string'&&x.length<130)])].sort((a,b)=>a.localeCompare(b));
    }
    category.brands=[...names].sort((a,b)=>a.localeCompare(b));
  }
  if(selected!=='car'){
    const state=formState();
    renderBrands();renderFilters();
    for(const [key,value] of Object.entries(state)){
      const field=extra.querySelector('[name="'+CSS.escape(key)+'"]');
      if(field){if(field.type==='checkbox')field.checked=value;else field.value=value;}
    }
    const mk=extra.querySelector('[name="make"]');if(mk){const previous=state.model;mk.dispatchEvent(new Event('change'));const field=extra.querySelector('[name="model"]');if(field){field.value=previous||'';if(previous&&!Array.from(field.options).some(o=>o.value===previous)){field.value='__avtovip_other_model__';field.dispatchEvent(new Event('change'));const manual=extra.querySelector('.vehicle-model-manual');if(manual)manual.value=previous;}}}
  }
}
